<?php $catalogInks=array_values(array_filter($rawMaterials,function($row){return !empty($row['is_ink']);}));$showInkCosts=gt_erp_user_can($pdo,$user,'erp.costs_view')||gt_erp_user_can($pdo,$user,'erp.master_data')||gt_erp_user_can($pdo,$user,'erp.purchases');if($catalogInks): ?>
<div class="card mb-3"><div class="card-body"><h3 class="h5">Tintas — manutenção de cores</h3><p class="text-muted small">Referências por artigo. Clique no cabeçalho para ordenar.</p>
<div class="table-responsive"><table class="table table-hover align-middle" data-sortable-table="Tintas"><thead><tr><th>Código</th><th>Cor</th><th>Pantone</th><th>Tinta água</th><th>Últ. preço</th><th>ID antigo</th><th></th></tr></thead><tbody>
<?php foreach($catalogInks as $ink):?><tr><td><?=h($ink['code'])?></td><td><?=h($ink['ink_color'])?></td><td><?=h($ink['ink_pantone'])?></td><td><?=!empty($ink['is_water_based_ink'])?'Sim':'Não'?></td><td><?=$showInkCosts?h(number_format((float)$ink['last_price'],4,',','.')):'—'?></td><td><?=h((string)$ink['legacy_ink_id'])?></td><td><?php if(gt_erp_user_can($pdo,$user,'erp.master_data')):?><a class="btn btn-sm btn-outline-primary" href="erp.php?page=raw_materials&amp;raw_material_id=<?=(int)$ink['id']?>#raw-material-editor">Editar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php endif; ?>
<?php if(gt_erp_user_can($pdo,$user,'erp.master_data')):$inkConflicts=$pdo->query('SELECT l.*,r.code FROM erp_ink_material_reconciliation_log l JOIN erp_raw_materials r ON r.id=l.material_id WHERE l.status="pending" ORDER BY r.code,l.id')->fetchAll(PDO::FETCH_ASSOC);if($inkConflicts): ?>
<div class="alert alert-warning"><h4 class="h6">Referências de tintas a confirmar</h4><p>Estes dados divergem da característica existente. Os valores foram conservados para revisão.</p><ul class="mb-0"><?php foreach($inkConflicts as $conflict):?><li><a href="erp.php?page=raw_materials&amp;raw_material_id=<?=(int)$conflict['material_id']?>#raw-material-editor"><?=h($conflict['code'])?></a>: <?=h(['ink_color'=>'Cor','ink_pantone'=>'Pantone','ink_type_id'=>'Tipo de tinta'][$conflict['field_name']]??$conflict['field_name'])?> — registado <?=h($conflict['previous_value'])?>; característica <?=h($conflict['derived_value'])?>.</li><?php endforeach;?></ul></div>
<?php endif;endif;?>
